import re


def parse_remote(url):
    if not isinstance(url, str):
        return None
    text = url.strip()
    if text.endswith('.git'):
        text = text[:-4]
    match = re.match(r'^https?://(?P<host>[^/]+)/(?P<owner>[^/]+)/(?P<repo>[^/]+)$', text)
    if not match:
        match = re.match(r'^[\w.\-]+@(?P<host>[^:]+):(?P<owner>[^/]+)/(?P<repo>[^/]+)$', text)
    if not match:
        return None
    return {'host': match.group('host'), 'owner': match.group('owner'), 'repo': match.group('repo')}


def check_branch(name):
    problems = []
    if not isinstance(name, str) or not name:
        return ['分支名不能为空']
    if not re.fullmatch(r'[a-z0-9\-/]+', name):
        problems.append('只能使用小写字母、数字、- 和 /')
    if name[0] in '-/' or name[-1] in '-/':
        problems.append('不能以 - 或 / 开头或结尾')
    if '--' in name or '//' in name:
        problems.append('出现了连续的符号')
    if len(name) > 20:
        problems.append('分支名过长（上限 20）')
    return problems


print(parse_remote('https://gitee.com/pymaster/team-project.git'))
print(parse_remote('git@gitee.com:pymaster/team-project.git'))
print(parse_remote('随便一段文字'))
print(check_branch('feature/login'))
print(check_branch('Feature_Login'))
print(check_branch('-feature--login-'))
